Here's a modern MSTest test class for `DataFetcher`:

```csharp
using System.Net;
using Microsoft.VisualStudio.TestTools.UnitTesting;

[TestClass]
public class DataFetcherTests
{
    // Modern MSTest: async Task tests are natively supported
    [TestMethod]
    public async Task FetchAsync_ReturnsContent_OnSuccess()
    {
        var handler = new FakeHandler(new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("hello")
        });
        var fetcher = new DataFetcher(new HttpClient(handler));

        var result = await fetcher.FetchAsync("https://example.com");

        Assert.AreEqual("hello", result);
    }

    // Use [Timeout] to guard against hangs (value in milliseconds)
    [TestMethod]
    [Timeout(3000)]
    public async Task FetchAsync_Throws_OnServerError()
    {
        var handler = new FakeHandler(new HttpResponseMessage(HttpStatusCode.InternalServerError));
        var fetcher = new DataFetcher(new HttpClient(handler));

        await Assert.ThrowsExceptionAsync<HttpRequestException>(
            () => fetcher.FetchAsync("https://example.com"));
    }

    // Test that cancellation is properly propagated
    [TestMethod]
    public async Task FetchAsync_Throws_WhenCancelled()
    {
        var handler = new FakeHandler(new HttpResponseMessage(HttpStatusCode.OK)
        {
            Content = new StringContent("data")
        }, simulateDelay: TimeSpan.FromSeconds(10));
        var fetcher = new DataFetcher(new HttpClient(handler));

        using var cts = new CancellationTokenSource();
        cts.Cancel(); // cancel immediately

        await Assert.ThrowsExceptionAsync<TaskCanceledException>(
            () => fetcher.FetchAsync("https://example.com", cts.Token));
    }

    // Minimal fake handler — no mocking library needed
    private sealed class FakeHandler : HttpMessageHandler
    {
        private readonly HttpResponseMessage _response;
        private readonly TimeSpan _delay;

        public FakeHandler(HttpResponseMessage response, TimeSpan simulateDelay = default)
        {
            _response = response;
            _delay = simulateDelay;
        }

        protected override async Task<HttpResponseMessage> SendAsync(
            HttpRequestMessage request, CancellationToken cancellationToken)
        {
            if (_delay > TimeSpan.Zero)
                await Task.Delay(_delay, cancellationToken);

            cancellationToken.ThrowIfCancellationRequested();
            return _response;
        }
    }
}
```

**Key patterns demonstrated:**

| Pattern | How |
|---|---|
| **Async tests** | Return `async Task` — MSTest awaits them natively (never `async void`) |
| **Timeout** | `[Timeout(ms)]` attribute — fails the test if it hangs |
| **Cancellation** | Pass a pre-cancelled `CancellationTokenSource` and assert `TaskCanceledException` |
| **No mock framework** | A custom `HttpMessageHandler` keeps dependencies minimal and cancellation-token propagation explicit |
